(() => {
  const ID = 'color-sort';
  const shell = () => window.TelePlayGameShell;
  const tg = window.Telegram?.WebApp;
  let screen, board, hint, movesEl, selected = -1, moves = 0, tubes = [], callbacks = {}, initialized = false, finished = false;
  const COLORS = ['cyan','pink','gold','violet'];
  const $ = id => document.getElementById(id);
  const haptic = type => { try { tg?.HapticFeedback?.impactOccurred(type); } catch (_) {} };
  function resetBoard() { tubes = [['cyan','pink','violet','gold'],['violet','gold','cyan','pink'],['pink','cyan','gold','violet'],[]]; moves = 0; selected = -1; finished = false; render(); }
  function render() { movesEl.textContent = moves; board.innerHTML = tubes.map((tube, index) => `<button type="button" class="sort-flask ${index === selected ? 'is-selected' : ''}" data-sort-tube="${index}" aria-label="Колба ${index + 1}">${tube.map(color => `<span class="sort-liquid ${color}"></span>`).join('')}</button>`).join(''); }
  function solved() { return tubes.every(tube => tube.length === 0 || (tube.length === 4 && tube.every(color => color === tube[0]))); }
  function pour(target) { if (finished) return; if (selected < 0) { if (!tubes[target].length) return; selected = target; hint.textContent = 'Теперь выбери колбу для переливания'; render(); haptic('light'); return; } if (selected === target) { selected = -1; hint.textContent = 'Выбери колбу с цветом'; render(); return; } const from = tubes[selected], to = tubes[target], color = from[from.length - 1]; if (!color || to.length >= 4 || (to.length && to[to.length - 1] !== color)) { hint.textContent = 'Сюда нельзя перелить этот цвет'; haptic('heavy'); return; } let amount = 0; while (from.length && from[from.length - 1] === color && to.length < 4) { to.push(from.pop()); amount += 1; } moves += 1; selected = -1; hint.textContent = `Перелито слоёв: ${amount}`; render(); haptic('light'); if (solved()) finish(); }
  function finish() { finished = true; const score = Math.max(100, 900 - moves * 35), previous = shell().getStats(ID), result = shell().saveResult(ID, score, { bestMoves: previous.bestMoves ? Math.min(previous.bestMoves, moves) : moves, lastResult: { score, moves } }), reward = Math.max(1, Math.floor(score / 160)); window.TelePlayCore?.RewardManager?.award(ID, { coins: reward, score, metadata: { transactionId: `game:${ID}:run:${Date.now()}`, moves, colors: COLORS.length } }); shell().emit('color_sort_finished', { gameId: ID, score, moves, reward }); shell().emit('game_finished', { gameId: ID, score, reward, moves, victory: true }); shell().ResultScreen.show(screen.querySelector('[data-sort-result]'), { score, bestScore: result.bestScore, reward, newRecord: result.newRecord, title: 'Цвета<br>собраны!', details: { moves, colors: `${COLORS.length} / ${COLORS.length}` } }); screen.querySelector('[data-sort-result]').hidden = false; }
  function start() { resetBoard(); screen.querySelector('[data-sort-start]').hidden = true; screen.querySelector('[data-sort-result]').hidden = true; shell().emit('color_sort_started', { gameId: ID }); shell().emit('game_started', { gameId: ID }); haptic('light'); }
  function open(options = {}) { callbacks = options; screen.hidden = false; screen.querySelector('[data-sort-start]').hidden = false; screen.querySelector('[data-sort-result]').hidden = true; const stats = shell().getStats(ID); screen.querySelector('[data-sort-menu-best]').textContent = Number(stats.bestScore || 0).toLocaleString('ru-RU'); resetBoard(); try { tg?.requestFullscreen?.(); tg?.disableVerticalSwipes?.(); } catch (_) {} }
  function hide() { screen.hidden = true; try { tg?.enableVerticalSwipes?.(); tg?.exitFullscreen?.(); } catch (_) {} }
  function close() { hide(); callbacks.onHome?.(); }
  function init() { if (initialized) return; initialized = true; screen = $('colorSortScreen'); screen.innerHTML = `<div class="color-sort-inner"><header class="color-sort-hud"><button class="icon-button" data-sort-close aria-label="На главную">×</button><div class="color-sort-brand"><small>TELEPLAY · ПАЗЛЫ</small><b>Color Sort</b></div><div class="color-sort-stat"><small>ХОДЫ</small><b data-sort-moves>0</b></div><button class="icon-button" data-sort-reset aria-label="Начать заново">↻</button></header><div class="color-sort-board" data-sort-board></div><p class="color-sort-hint" data-sort-hint>Выбери колбу с верхним цветом</p><div class="color-sort-actions"><button class="secondary-button" type="button" data-sort-reset-action>Перемешать</button><button class="play-button" type="button" data-sort-check>Проверить</button></div></div><div class="start-panel" data-sort-start><span class="panel-kicker">TELEPLAY · ПАЗЛЫ</span><h2>Color<br>Sort</h2><p>Переливай цветные слои.<br>Собери каждый цвет в одну колбу.</p><button class="play-button large" data-sort-start-button>Начать сортировку</button><div class="record">Лучший результат: <b data-sort-menu-best>0</b></div></div><div class="start-panel result-panel" data-sort-result hidden><span class="panel-kicker" data-result="kicker">СОРТИРОВКА ЗАВЕРШЕНА</span><h2 data-result="title">Цвета<br>собраны!</h2><div class="result-score"><small>РЕЗУЛЬТАТ</small><b data-result="score">0</b></div><div class="result-details"><span>Лучший результат <b data-result="best">0</b></span><span>Получено <b data-result="reward">+0 🪙</b></span><span>Ходы <b data-result="moves">0</b></span><span>Цвета <b data-result="colors">0 / 4</b></span></div><button class="play-button large" data-sort-replay>Новая партия</button><button class="text-button" data-sort-home>На главную</button></div>`; board = screen.querySelector('[data-sort-board]'); hint = screen.querySelector('[data-sort-hint]'); movesEl = screen.querySelector('[data-sort-moves]'); board.addEventListener('click', event => { const tube = event.target.closest('[data-sort-tube]'); if (tube) pour(Number(tube.dataset.sortTube)); }); screen.querySelector('[data-sort-start-button]').addEventListener('click', start); screen.querySelector('[data-sort-replay]').addEventListener('click', start); screen.querySelector('[data-sort-home]').addEventListener('click', close); screen.querySelector('[data-sort-close]').addEventListener('click', close); screen.querySelector('[data-sort-reset]').addEventListener('click', resetBoard); screen.querySelector('[data-sort-reset-action]').addEventListener('click', resetBoard); screen.querySelector('[data-sort-check]').addEventListener('click', () => { hint.textContent = solved() ? 'Готово!' : 'В каждой колбе должен остаться один цвет'; }); resetBoard(); }
  window.ColorSortGame = { init, open, hide, close, start, restart: start, destroy: hide };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', init) : init();
})();
